import FreeCAD as App
import Part

doc = App.activeDocument
if doc:
    # Find the Pad001 object
    obj = doc.Pad001
    if obj:
        print(f"Found Pad001. Type: {type(obj)}")
        shape = obj.Shape
        print(f"Shape Type: {type(shape)}")
        if isinstance(shape, Part.Compound):
            print(f"Number of shapes in compound: {len(shape.Shapes)}")
            for i, s in enumerate(shape.Shapes):
                print(f"Shape {i}: {s.ShapeType} - Volume: {s.Volume}, Area: {s.Area}")
        else:
            print(f"Shape is not a compound: {shape.ShapeType} - Volume: {shape.Volume}, Area: {shape.Area}")
    else:
        print("Pad001 not found in active document.")
else:
    print("No active document.")

