import FreeCAD as App
import Part

doc = App.activeDocument
pad001 = doc.Pad001
if pad001:
    print(f"Pad001 Shape Type: {type(pad001.Shape)}")
    # Check if it is a compound and if it contains multiple solids
    if isinstance(pad001.Shape, Part.Compound):
        print(f"Number of shapes in compound: {len(pad001.Shape.Shapes)}")
        for i, s in enumerate(pad001.Shape.Shapes):
            print(f"Shape {i}: {s.ShapeType} - Volume: {s.Volume}")
    else:
        print(f"Shape is {pad001.Shape.ShapeType} - Volume: {pad001.Shape.Volume}")
else:
    print("Pad001 not found.")

import FreeCAD as App
import Part

doc = App.activeDocument
# Iterate through all objects in the document to find the Pad001
pad001 = None
for obj in doc.Objects:
    if obj.Name == "Pad001":
        pad001 = obj
        break

if pad001:
    print(f"Found Pad001. Type: {type(pad001)}")
    shape = pad001.Shape
    print(f"Shape Type: {type(shape)}")
    if isinstance(shape, Part.Compound):
        print(f"Number of shapes in compound: {len(shape.Shapes)}")
        for i, s in enumerate(shape.Shapes):
            print(f"Shape {i}: {s.ShapeType} - Volume: {s.Volume}")
    else:
        print(f"Shape is not a compound: {shape.ShapeType} - Volume: {shape.Volume}")
else:
    print("Pad001 not found in active document.")

